#include <iostream>
#include <vector>
using namespace std;

vector<long long> ones(20);

int count_ones(long long n, int i) {
    if (n == 0 || i == 0) return 0;
    long long current_power = ones[i];
    int count = 0;
    long long temp = n;
    while (temp >= current_power) {
        temp -= current_power;
        count += i;
    }
    if (temp == 0) return count;
    int option1 = i + count_ones(ones[i] - temp, i - 1);
    int option2 = count_ones(temp, i - 1);
    return count + min(option1, option2);
}

