    ones[0] = 0;
    for (int i = 1; i <= 16; ++i) {
        ones[i] = ones[i - 1] * 10 + 1;
    }
    long long n;
    cin >> n;
    cout << count_ones(n, 16) << endl;
    return 0;
}
