import java.util.Scanner;

public class Main {
    static long[] ones = new long[20];

    static int countOnes(long n, int i) {
        if (n == 0 || i == 0) return 0;
        long currentPower = ones[i];
        int count = 0;
        long temp = n;
        while (temp >= currentPower) {
            temp -= currentPower;
            count += i;
        }
        if (temp == 0) return count;
        int option1 = i + countOnes(ones[i] - temp, i - 1);
        int option2 = countOnes(temp, i - 1);
        return count + Math.min(option1, option2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ones[0] = 0;
        for (int i = 1; i <= 16; ++i) {
            ones[i] = ones[i - 1] * 10 + 1;
        }
        long n = scanner.nextLong();
        System.out.println(countOnes(n, 16));
        scanner.close();
    }
}
